from pathlib import Path

def replace_once(path_str, old, new, label):
    path = Path(path_str)
    source = path.read_text()
    if new in source:
        return
    if old not in source:
        raise SystemExit(f"{label} did not match")
    path.write_text(source.replace(old, new, 1))

